const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const uk = ee.FeatureCollection('FAO/GAUL/2015/level0')
    .filter(ee.Filter.eq('ADM0_NAME', 'United Kingdom of Great Britain and Northern Ireland'));

  const febPeriod2019 = ['2019-02-11', '2019-02-26'];
  const historicalPeriods = [];
  for (let year = 2000; year <= 2012; year++) {
    historicalPeriods.push([`${year}-02-11`, `${year}-02-26`]);
  }

  // 2. Data Acquisition - MODIS LST
  const getLSTCollection = function(startDate, endDate) {
    return ee.ImageCollection('MODIS/061/MOD11A2')
      .filterDate(startDate, endDate)
      .filterBounds(uk)
      .select(['LST_Day_1km', 'QC_Day']);
  };

  // Function to process LST with quality masking
  const processLST = function(image) {
    const lst = image.select('LST_Day_1km').multiply(0.02).subtract(273.15); // Convert to Celsius
    const qc = image.select('QC_Day');
    const qualityMask = qc.bitwiseAnd(parseInt('11', 2)).eq(0); // Good quality pixels
    return lst.updateMask(qualityMask);
  };

  // Get 2019 data
  const lst2019Col = getLSTCollection(febPeriod2019[0], febPeriod2019[1]);
  const lst2019Size = lst2019Col.size().getInfo();

  if (lst2019Size === 0) {
    console.log("2019 Images: 0");
    console.log("<answer>C1</answer>");
    return;
  }

  // Get historical data
  const historicalCollections = historicalPeriods.map(period => 
    getLSTCollection(period[0], period[1])
  );

  const historicalSizes = historicalCollections.map(col => col.size().getInfo());
  const validHistorical = historicalSizes.filter(size => size > 0).length;

  if (validHistorical === 0) {
    console.log(`2019 Images: ${lst2019Size}, Historical: 0 valid years`);
    console.log("<answer>C1</answer>");
    return;
  }

  // Process 2019 data
  const lst2019 = lst2019Col.map(processLST).mean();

  // Process historical data
  const historicalMeans = historicalCollections
    .filter(col => col.size().getInfo() > 0)
    .map(col => col.map(processLST).mean());

  const historicalComposite = ee.ImageCollection(historicalMeans).mean();

  // Check pixel counts
  const count2019 = lst2019.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: uk,
    scale: 1000,
    maxPixels: 1e9
  }).get('LST_Day_1km').getInfo();

  const countHistorical = historicalComposite.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: uk,
    scale: 1000,
    maxPixels: 1e9
  }).get('LST_Day_1km').getInfo();

  if (count2019 === 0 || countHistorical === 0) {
    console.log(`2019 Pixels: ${count2019}, Historical Pixels: ${countHistorical}`);
    console.log("<answer>C2</answer>");
    return;
  }

  // Calculate means
  const mean2019 = lst2019.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: uk,
    scale: 1000,
    maxPixels: 1e9
  }).get('LST_Day_1km').getInfo();

  const meanHistorical = historicalComposite.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: uk,
    scale: 1000,
    maxPixels: 1e9
  }).get('LST_Day_1km').getInfo();

  // Validation
  if (mean2019 === null || meanHistorical === null || 
      isNaN(mean2019) || isNaN(meanHistorical) ||
      Math.abs(mean2019) > 60 || Math.abs(meanHistorical) > 60) { // Sanity check for LST range
    console.log(`2019 Mean: ${mean2019}, Historical Mean: ${meanHistorical}`);
    console.log("<answer>C3</answer>");
    return;
  }

  // Final comparison
  console.log(`2019 Images: ${lst2019Size}, Historical Years: ${validHistorical}/13`);
  console.log(`2019 Temp: ${mean2019.toFixed(2)}°C, Historical: ${meanHistorical.toFixed(2)}°C`);
  console.log(`Difference: ${(mean2019 - meanHistorical).toFixed(2)}°C`);
  console.log(`2019 Pixels: ${count2019}, Historical Pixels: ${countHistorical}`);

  if (mean2019 > meanHistorical) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
